import { describe, expect, it } from "vitest";

import { averageRates, TrafficFrameResponseSchema } from "./trafficService.ts";

// Fixtures are generated by `cargo test --test serialize_fixtures` in
// src-tauri from the real serde output of traffic::FrameResponse.
// When the Rust type changes, re-run that test to regenerate; if this file
// then fails, update TrafficFrameResponseSchema to match the new wire format.
import frame from "./fixtures/traffic_frame.json";
import failed from "./fixtures/traffic_frame_failed.json";

describe("TrafficFrameResponseSchema fixtures", () => {
  it("parses a running capture", () => {
    const parsed = TrafficFrameResponseSchema.safeParse(frame);
    expect(parsed.success).toBe(true);
    if (!parsed.success) return;
    expect(parsed.data.capture.active).toBe(true);
    expect(parsed.data.capture.interface).toBe("en0");
    expect(parsed.data.frame.window_seconds).toBe(10);
    expect(parsed.data.frame.observed_seconds).toBe(10);
    expect(parsed.data.frame.endpoints).toHaveLength(5);
    expect(parsed.data.frame.endpoints[0].id).toBe("9f2c4e81a07b3d56");
    expect(parsed.data.frame.endpoints[0].received).toBe(4_800_000);
    expect(parsed.data.frame.endpoints[4].received).toBe(0);
    expect(parsed.data.frame.omitted_endpoints).toBe(0);
  });

  it("parses a failed capture with no endpoints", () => {
    const parsed = TrafficFrameResponseSchema.safeParse(failed);
    expect(parsed.success).toBe(true);
    if (!parsed.success) return;
    expect(parsed.data.capture.active).toBe(false);
    expect(parsed.data.capture.interface).toBeNull();
    expect(parsed.data.capture.error).toBe(
      "The Gnosis VPN service is not running",
    );
    expect(parsed.data.frame.endpoints).toHaveLength(0);
    expect(parsed.data.gap).toBe(true);
  });

  it("rejects negative and fractional byte totals", () => {
    const negative = JSON.parse(JSON.stringify(frame));
    negative.frame.endpoints[0].sent = -1;
    expect(TrafficFrameResponseSchema.safeParse(negative).success).toBe(false);

    const fractional = JSON.parse(JSON.stringify(frame));
    fractional.frame.endpoints[0].received = 1.5;
    expect(TrafficFrameResponseSchema.safeParse(fractional).success).toBe(
      false,
    );
  });

  it("rejects an endpoint that carries an address", () => {
    const leaky = JSON.parse(JSON.stringify(frame));
    leaky.frame.endpoints[0].target = "203.0.113.9";
    expect(TrafficFrameResponseSchema.safeParse(leaky).success).toBe(false);
  });
});

describe("averageRates", () => {
  it("averages each direction over the observed seconds", () => {
    const parsed = TrafficFrameResponseSchema.parse(frame);
    const rates = averageRates(parsed.frame);
    expect(rates.sent).toBe((120_000 + 300_000 + 12_000 + 2_400 + 600) / 10);
    expect(rates.received).toBe((4_800_000 + 90_000 + 40_000 + 6_100) / 10);
  });

  it("is zero before the first second completes", () => {
    const parsed = TrafficFrameResponseSchema.parse(failed);
    expect(averageRates(parsed.frame)).toEqual({ sent: 0, received: 0 });
  });
});
